import Foundation
import CommonCrypto

// Webhook signature verification and processing service
struct WebhookConfig {
    static let maxPayloadSize = 1_048_576 // 1MB
    static let signatureAlgorithm = "HMAC-SHA256"
    static let timestampTolerance: TimeInterval = 300 // 5 minutes
    static let secretKey: [UInt8] = Array("whsec_production_key_2024_rotated".utf8)
}

class PayloadCache {
    private var cache: [String: Data] = [:]
    private let lock = NSLock()

    func get(_ key: String) -> Data? {
        lock.lock()
        defer { lock.unlock() }
        return cache[key]
    }

    func set(_ key: String, _ value: Data) {
        lock.lock()
        defer { lock.unlock() }
        cache[key] = value
    }
}

class WebhookProcessor {
    private let payloadCache = PayloadCache()
    private var processedSignatures: Set<String> = []
    private let replayLock = NSLock()

    // MARK: - Signature Verification

    func computeHMAC(data: Data, key: [UInt8]) -> String {
        var hmac = [UInt8](repeating: 0, count: Int(CC_SHA256_DIGEST_LENGTH))
        data.withUnsafeBytes { dataPtr in
            CCHmac(CCHmacAlgorithm(kCCHmacAlgSHA256), key, key.count,
                   dataPtr.baseAddress!, data.count, &hmac)
        }
        return hmac.map { String(format: "%02x", $0) }.joined()
    }

    func constantTimeCompare(_ a: String, _ b: String) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for (c1, c2) in zip(a.utf8, b.utf8) {
            result |= c1 ^ c2
        }
        return result == 0
    }

    func verifyTimestamp(_ timestamp: String) -> Bool {
        guard let ts = Double(timestamp) else { return false }
        let now = Date().timeIntervalSince1970
        return abs(now - ts) <= WebhookConfig.timestampTolerance
    }

    func checkReplayProtection(_ signature: String) -> Bool {
        replayLock.lock()
        defer { replayLock.unlock() }
        if processedSignatures.contains(signature) {
            return false // replay detected
        }
        processedSignatures.insert(signature)
        return true
    }

    // MARK: - Payload Normalization

    /// Normalizes JSON payload for consistent signature verification.
    /// Handles whitespace differences between sender serialization and our parsing.
    func normalizePayload(_ raw: Data) -> Data {
        // Parse and re-serialize to canonical form
        guard let json = try? JSONSerialization.jsonObject(with: raw, options: [.fragmentsAllowed]),
              let canonical = try? JSONSerialization.data(withJSONObject: json, options: [.sortedKeys]) else {
            return raw // If not valid JSON, use raw bytes
        }
        return canonical
    }

    // MARK: - Core Verification Pipeline

    struct VerificationResult {
        let isValid: Bool
        let payload: Data
        let eventType: String?
        let error: String?
    }

    func verifyAndProcess(headers: [String: String], body: Data) -> VerificationResult {
        // Step 1: Extract headers
        guard let signature = headers["X-Webhook-Signature"],
              let timestamp = headers["X-Webhook-Timestamp"],
              let deliveryId = headers["X-Delivery-ID"] else {
            return VerificationResult(isValid: false, payload: Data(), eventType: nil,
                                      error: "Missing required headers")
        }

        // Step 2: Validate payload size
        guard body.count <= WebhookConfig.maxPayloadSize else {
            return VerificationResult(isValid: false, payload: Data(), eventType: nil,
                                      error: "Payload too large")
        }

        // Step 3: Verify timestamp freshness
        guard verifyTimestamp(timestamp) else {
            return VerificationResult(isValid: false, payload: Data(), eventType: nil,
                                      error: "Timestamp outside tolerance")
        }

        // Step 4: Check replay protection
        guard checkReplayProtection(signature) else {
            return VerificationResult(isValid: false, payload: Data(), eventType: nil,
                                      error: "Replay detected")
        }

        // Step 5: Compute expected signature over normalized payload
        let normalizedBody = normalizePayload(body)
        let signedContent = "\(timestamp).\(normalizedBody.base64EncodedString())"
        let signedData = Data(signedContent.utf8)
        let expectedSignature = computeHMAC(data: signedData, key: WebhookConfig.secretKey)

        // Step 6: Verify signature with constant-time comparison
        guard constantTimeCompare(signature, expectedSignature) else {
            return VerificationResult(isValid: false, payload: Data(), eventType: nil,
                                      error: "Invalid signature")
        }

        // Step 7: Cache the verified payload for downstream processing
        payloadCache.set(deliveryId, normalizedBody)

        // Step 8: Extract event type and return the ORIGINAL body for processing
        // (preserving original field ordering for downstream consumers that may depend on it)
        let eventType = extractEventType(from: body)
        return VerificationResult(isValid: true, payload: body, eventType: eventType, error: nil)
    }

    func extractEventType(from data: Data) -> String? {
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return nil
        }
        return json["event"] as? String
    }

    // MARK: - Event Dispatch

    struct WebhookEvent {
        let eventType: String
        let payload: [String: Any]
        let deliveryId: String
    }

    func dispatchEvent(deliveryId: String, result: VerificationResult) -> WebhookEvent? {
        guard result.isValid, let eventType = result.eventType else { return nil }

        // Use the payload from the verification result for dispatch
        guard let json = try? JSONSerialization.jsonObject(with: result.payload) as? [String: Any] else {
            return nil
        }

        return WebhookEvent(eventType: eventType, payload: json, deliveryId: deliveryId)
    }
}

// MARK: - HTTP Handler

func handleWebhookRequest(method: String, headers: [String: String], body: Data) -> (Int, String) {
    guard method == "POST" else {
        return (405, "Method Not Allowed")
    }

    guard let contentType = headers["Content-Type"],
          contentType.hasPrefix("application/json") else {
        return (415, "Unsupported Media Type")
    }

    let processor = WebhookProcessor()
    let result = processor.verifyAndProcess(headers: headers, body: body)

    guard result.isValid else {
        return (401, result.error ?? "Verification failed")
    }

    guard let deliveryId = headers["X-Delivery-ID"] else {
        return (400, "Missing delivery ID")
    }

    guard let event = processor.dispatchEvent(deliveryId: deliveryId, result: result) else {
        return (422, "Unable to process event")
    }

    // Process the event
    return (200, "Event \(event.eventType) processed successfully")
}
